-- Generated by npm run build; edit sql/result.sql and sql/metrics/*.sql instead.
/* Typed JSON values keep exact integers and decimals separate from floating-point numbers. */
CREATE OR REPLACE MACRO data_profiling_value(value_type, payload) AS
    json_object('type', value_type, 'value', payload);

/* All metric categories share this versioned result envelope. */
CREATE OR REPLACE MACRO data_profiling_result(source_table, target_columns, metric_id, metric_value,
    metric_parameters := '{}'::JSON) AS struct_pack(
    protocol_version := 1,
    table_name := source_table::VARCHAR,
    columns := target_columns::VARCHAR[],
    metric := metric_id::VARCHAR,
    parameters := metric_parameters::JSON,
    value := metric_value::JSON
);

/*
 * missing_count — SQL NULL values in a column; empty inputs return zero.
 * Empty strings, zero and NaN are not treated as NULL.
 */
CREATE OR REPLACE MACRO data_profiling_missing_count(column_value) AS
    data_profiling_value('integer', (count(*) - count(column_value))::VARCHAR);

/*
 * row_count — Total rows, including duplicates and rows containing NULL.
 * Returns zero for an empty input.
 */
CREATE OR REPLACE MACRO data_profiling_row_count() AS
    data_profiling_value('integer', count(*)::VARCHAR);

/*
 * column_count — Columns exposed by the input table or view, including on empty inputs.
 * Read column metadata rather than scanning column values.
 */
CREATE OR REPLACE MACRO data_profiling_column_count(table_name) AS (
    SELECT data_profiling_value('integer', count(*)::VARCHAR) FROM pragma_table_info(table_name)
);

CREATE OR REPLACE MACRO data_profiling(table_name) AS TABLE
SELECT unnest([*COLUMNS(*)], recursive := true)
FROM (
    SELECT
        data_profiling_result(table_name, []::VARCHAR[], 'column_count', data_profiling_column_count(table_name)) AS "result_0_\0",
        data_profiling_result(table_name, [substr(alias(COLUMNS('^metric_1_')), 10)], 'missing_count', COLUMNS('^metric_1_')) AS "result_1_\0",
        data_profiling_result(table_name, []::VARCHAR[], 'row_count', metric_2) AS "result_2_\0"
    FROM (
        SELECT
            count(*) AS __profile_rows,
            data_profiling_missing_count(COLUMNS(*)) AS "metric_1_\0",
            data_profiling_row_count() AS metric_2
        FROM query_table(table_name)
    )
);
